//  CommittedChatDB
//  A private copy of a committed `chat.db` fixture, made one way and removed one way.
//
//  The fixtures under `Tests/BBIMessageTests/ChatDBFixtures` are real Apple schemas, one per
//  supported macOS release, generated by `Tools/chatdb-fixtures/generate.py`. A test never
//  opens one in place: SQLite places `-wal` and `-shm` beside whatever it opens, and a suite
//  that seeds rows before opening read-only would be writing into the committed file. So
//  every suite copies first, and this is the one place that knows where the fixtures are and
//  how a copy is made and removed.
//
//  A copy lives in a directory of its own, named `chat.db` as the real one is, so removing it
//  removes its sidecars with it, and anything a suite put beside it.
//
//  **A copy belongs to a scope, and cannot be made outside one.** `copy` registers what it
//  makes with the enclosing `withCopies` (or the `.removingChatDBCopies` trait, which is that
//  scope around each test), and the scope removes every copy when it ends, on every path. A
//  copy made with no scope throws `CommittedChatDBError.noScope` rather than succeeding,
//  because a removal each call site has to remember is one some site forgets, and the
//  commonest site cannot remember it at all: a factory that makes the copy and returns an
//  interface leaves no caller holding the path. Asking for the scope instead turns a
//  forgotten removal into a test that fails on its first run, rather than a temporary
//  directory that fills a little on every `swift test`.
//
//  Not to be confused with BBIMessageTests' `ChatDatabaseFixture`, which builds a synthetic
//  modern schema from scratch. This one is Apple's schemas, as committed, with their rows.

import Foundation
import GRDB
import Testing

public enum CommittedChatDB {

  /// The releases a fixture is committed for. The raw value is the file's suffix.
  public enum Release: String, CaseIterable, Sendable {
    case ventura, sonoma, sequoia
  }

  /// Where the committed fixtures live.
  public static let directory = Repository.url("Tests/BBIMessageTests/ChatDBFixtures")

  /// The committed fixture for `release`. Never open it directly; take a `copy`.
  public static func source(_ release: Release) -> URL {
    directory.appendingPathComponent("chat-\(release.rawValue).db")
  }

  /// Runs `body` in a scope that removes every copy made inside it when it ends.
  ///
  /// A suite reaches this through the `.removingChatDBCopies` trait; a harness that owns a
  /// lifecycle of its own (`ReplayServer.run`) calls it directly. Scopes nest, and a copy
  /// belongs to the innermost.
  public static func withCopies<Result>(
    isolation: isolated (any Actor)? = #isolation,
    _ body: () async throws -> Result
  ) async rethrows -> Result {
    let scope = CopyScope()
    defer { scope.removeAll() }
    return try await $currentScope.withValue(scope) { try await body() }
  }

  /// A private copy of a fixture, at `<a directory of its own>/chat.db`, removed when the
  /// enclosing scope ends. A suite may put other files in `deletingLastPathComponent()` of
  /// the result; they go with it.
  ///
  /// - Throws: `CommittedChatDBError.noScope` outside `withCopies` or `.removingChatDBCopies`.
  public static func copy(_ release: Release = .sonoma) throws -> URL {
    guard let scope = currentScope else { throw CommittedChatDBError.noScope }
    let target = FileManager.default.temporaryDirectory
      .appendingPathComponent("\(privatePrefix)\(UUID().uuidString)", isDirectory: true)
    scope.adopt(target)
    return try copy(release, into: target)
  }

  /// A private copy of a fixture, at `<directory>/chat.db`, in a directory the caller owns.
  ///
  /// For a suite that keeps other files beside the copy (an index, an upload) in a directory
  /// it already creates and removes. Nothing here removes it: it is theirs.
  public static func copy(_ release: Release = .sonoma, into directory: URL) throws -> URL {
    try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
    let copy = directory.appendingPathComponent("chat.db")
    try FileManager.default.copyItem(at: source(release), to: copy)
    return copy
  }

  /// A private copy of a fixture, converted to WAL, with a writable connection already open.
  /// Removed when the enclosing scope ends, as `copy` is.
  ///
  /// **Why this exists at all.** The committed fixtures are in rollback-journal mode, because
  /// the generator never sets one and SQLite's default is `delete`. A real `chat.db` is in
  /// WAL: Messages puts it there, and the file header says so. That difference is invisible
  /// until a test opens the file TWICE, once read-only through `ReadOnlyDatabase` and once
  /// writable to stand in for Messages, which is exactly what the hydration tests do.
  ///
  /// In rollback-journal mode a reader's SHARED lock blocks a writer, and with both
  /// connections in one process SQLite answers `BEGIN IMMEDIATE` with `SQLITE_IOERR_LOCK`
  /// (extended 3850), reported as "SQLite error 10: disk I/O error". Measured: 100% of
  /// attempts in that mode, 0% in WAL. It looked load-dependent only because load widened the
  /// window in which the reader's transaction and the writer's overlapped; the conflict itself
  /// is not a race.
  ///
  /// A busy timeout does NOT fix it. `Configuration.busyMode` retries `SQLITE_BUSY`; this is
  /// `SQLITE_IOERR`, and it is returned immediately whatever the busy handler says.
  ///
  /// **The order below is load-bearing.** The writable connection is opened FIRST and returned
  /// to the caller to hold, because a read-only connection cannot create the `-shm` file a WAL
  /// database needs: open one against a WAL file with no sidecars and it fails with
  /// `SQLITE_CANTOPEN`. The sidecars exist only while some connection holds them, so the
  /// writer has to outlive the reader's open, and it has to have actually WRITTEN, since the
  /// PRAGMA alone flips the header without materialising the files.
  ///
  /// - Returns: the path, and the writable connection. **Keep the connection for as long as
  ///   any reader is open**: releasing it lets SQLite remove `-wal` and `-shm`, after which a
  ///   read-only open of the same file fails.
  /// - Throws: `CommittedChatDBError.noScope` outside `withCopies` or `.removingChatDBCopies`.
  public static func walCopy(
    _ release: Release = .sonoma
  ) throws -> (path: String, writer: DatabaseQueue) {
    let path = try copy(release)
    let writer = try DatabaseQueue(path: path.path)
    try writer.writeWithoutTransaction { db in
      _ = try String.fetchOne(db, sql: "PRAGMA journal_mode = WAL")
    }
    // A real write, to materialise `-wal` and `-shm`. A no-op UPDATE is enough and changes
    // nothing a test can observe.
    try writer.write { db in
      try db.execute(sql: "UPDATE message SET ROWID = ROWID WHERE 0")
    }
    return (path.path, writer)
  }

  /// The scope `copy` registers with. Task-local, so a copy made in a child task belongs to
  /// the test that started it, and two tests running in parallel never share one.
  @TaskLocal private static var currentScope: CopyScope?

  /// Names a directory `copy` made.
  private static let privatePrefix = "bb-chatdb-"
}

/// What `CommittedChatDB` refuses.
public enum CommittedChatDBError: Error, CustomStringConvertible {
  case noScope

  public var description: String {
    switch self {
    case .noScope:
      "CommittedChatDB.copy was called outside a scope, so nothing would remove the copy. "
        + "Add `.removingChatDBCopies` to the suite, or wrap the work in "
        + "`CommittedChatDB.withCopies`."
    }
  }
}

/// The directories one scope's copies live in.
///
/// Locked because a test may copy from more than one task. Each removal is `try?` because a
/// directory that is already gone is the outcome wanted, and one that cannot be removed
/// leaves litter in the temporary directory, which no test asserts on.
private final class CopyScope: @unchecked Sendable {
  private let lock = NSLock()
  private var directories: [URL] = []

  func adopt(_ directory: URL) { lock.withLock { directories.append(directory) } }

  func removeAll() {
    for directory in lock.withLock({ directories }) {
      try? FileManager.default.removeItem(at: directory)
    }
  }
}

/// Every `CommittedChatDB` copy made during a test is removed when the test ends.
///
/// On a suite it applies to each test, and to each case of a parameterised one, so tests
/// running in parallel never wait on or remove each other's copies.
public struct RemovingChatDBCopies: SuiteTrait, TestTrait, TestScoping {
  public var isRecursive: Bool { true }

  public func provideScope(
    for test: Test, testCase: Test.Case?, performing function: @Sendable () async throws -> Void
  ) async throws {
    try await CommittedChatDB.withCopies { try await function() }
  }
}

extension Trait where Self == RemovingChatDBCopies {
  /// Removes every `CommittedChatDB` copy a test makes when the test ends.
  public static var removingChatDBCopies: Self { Self() }
}
